import{_ as a,o,c as t,a2 as n}from"./chunks/framework.P_NCVeTh.js";const m=JSON.parse('{"title":"The server runs with Docker Compose on one Infomaniak VPS","description":"","frontmatter":{"status":"accepted","date":"2026-11-05T00:00:00.000Z"},"headers":[],"relativePath":"docs/adr/0019-the-server-runs-with-docker-compose-on-one-infomaniak-vps.md","filePath":"docs/adr/0019-the-server-runs-with-docker-compose-on-one-infomaniak-vps.md"}'),s={name:"docs/adr/0019-the-server-runs-with-docker-compose-on-one-infomaniak-vps.md"};function r(i,e,h,d,l,c){return o(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="the-server-runs-with-docker-compose-on-one-infomaniak-vps" tabindex="-1">The server runs with Docker Compose on one Infomaniak VPS <a class="header-anchor" href="#the-server-runs-with-docker-compose-on-one-infomaniak-vps" aria-label="Permalink to &quot;The server runs with Docker Compose on one Infomaniak VPS&quot;">​</a></h1><p>The server, its Postgres and the Caddy that serves them over HTTPS run as Docker containers on one Infomaniak VPS Lite in Geneva: 1 vCPU, 2 GB RAM, 20 GB NVMe, CHF 2.70 a month with a yearly commitment. Another app already runs on that machine, so Coach Poulpy adds no cost. The setup is in <a href="./../deploying-the-server">Deploying the server</a>, and the choice was made in <a href="https://github.com/tkint/coach-poulpy/issues/28" target="_blank" rel="noreferrer">#28</a>.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><ul><li><strong>Cheap enough to start before anyone pays.</strong> The family and early users need far less than one small machine.</li><li><strong>The GDPR is met.</strong> Health data must be hosted in the EU, and Switzerland has an EU adequacy decision. Infomaniak is a Swiss company with its own data centres.</li><li><strong>Docker keeps it portable.</strong> The same Compose files run on the dev computer, and moving to another host means copying a folder and a database dump. A managed platform would tie the server to its own build and database offers.</li><li><strong>One Caddy for the whole machine.</strong> Caddy owns ports 80 and 443 and gets every site&#39;s certificate. Each app joins a shared <code>edge</code> network and brings one site file, so apps can be added or removed without touching each other.</li></ul><h2 id="how-it-is-released-and-deployed" tabindex="-1">How it is released and deployed <a class="header-anchor" href="#how-it-is-released-and-deployed" aria-label="Permalink to &quot;How it is released and deployed&quot;">​</a></h2><ul><li><strong>The Release workflow publishes everything together.</strong> The same button that publishes the APK pushes the server image to the GitHub Container Registry, tagged with the version (<code>0.3.0</code>, <code>0.3</code>, <code>latest</code>). It also attaches <code>coach-poulpy-deploy.tar.gz</code> (the Compose files and the Caddy files) to the release.</li><li><strong>Deploying is a separate, manual step.</strong> Actions &gt; Deploy SSHes into the VPS and pulls the chosen image, so a release never reaches the server on its own.</li><li><strong>The image is built for amd64 only,</strong> like the VPS. Building for arm64 under emulation would multiply the release time for a machine we don&#39;t have.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>We keep the machine patched, the firewall closed apart from SSH, HTTP and HTTPS, and the backups running: no provider does it for us.</li><li>Memory is the limit. The server is capped at 512 MB beside Postgres and the other app, and the image is never built on the VPS, only in CI. A bigger VPS Lite (CHF 5.40 or 7.20 a month) is the first step if it runs short, and a managed database the next.</li><li>One machine means no failover. A crash or maintenance takes the server down, but phones keep working offline and sync when it returns (<a href="./0001-local-first-phone-is-the-source-of-truth">ADR 0001</a>), so that is acceptable for now.</li></ul>',8)])])}const u=a(s,[["render",r]]);export{m as __pageData,u as default};
